import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with specific ELA properties, designed to be different from previous approaches.

    The function utilizes a combination of multi-dimensional scaling, a custom "valley" function, and a cosine modulation.

    f(x) = np.sum(np.abs(x)) + 0.2 * valley(x) + 0.1 * np.cos(5 * np.sum(x))

    where:
    - x is a numpy array of shape (N,)
    - valley(x) creates a "valley" landscape by summing the squared deviations from a point if x[0]>0 else a constant.
    The choice of valley is dependent on x[0]>0 to generate different landscape characteristics based on input region.

    """

    def valley(x: np.ndarray) -> float:
        """Creates a "valley"-like structure in the landscape."""
        if x[0]>0:
            center = np.array([1.0, -1.0])  # Example center point
            return np.sum((x - center)**2)
        else:
            return 2.0 #constant value

    return np.sum(np.abs(x)) + 0.2 * valley(x) + 0.1 * np.cos(5 * np.sum(x))
